create procedure "DA_CALC_ORDER_QUANTILE_INTERVAL" () LANGUAGE SQLSCRIPT  SQL SECURITY INVOKER  as begin     declare buycount int;     declare orderforquantile95 int;     declare ORDED_BUY table ("DocDate" timestamp, "CardCode" nvarchar(50), "RowNum" BIGINT);     declare INVOICE_BUY table ("DocDate" timestamp, "CardCode" nvarchar(50), "RowNum" BIGINT);     declare ORDED_BUY_INTERVAL table (DAYDIFF int, "CardCode" nvarchar(50));     declare INTERVAL_95 table (DAYDIFF int);     ORDED_BUY = (select "DocDate", "CardCode", ROW_NUMBER() over (partition by "CardCode" order by "DocDate") as "RowNum" from ORDR);     INVOICE_BUY = (select "DocDate", "CardCode", ROW_NUMBER() over (partition by "CardCode" order by "DocDate") as "RowNum" from OINV);     ORDED_BUY_INTERVAL =  select * from (select DAYS_BETWEEN(A."DocDate", B."DocDate") as DAYDIFF, A."CardCode" from :ORDED_BUY A inner join :ORDED_BUY B     on A."CardCode" = B."CardCode" and A."RowNum" = (B."RowNum" - 1)) SA union all  (select DAYS_BETWEEN(A."DocDate", B."DocDate") as DAYDIFF, A."CardCode" from :INVOICE_BUY A inner join :INVOICE_BUY B     on A."CardCode" = B."CardCode" and A."RowNum" = (B."RowNum" - 1)) order by DAYDIFF desc;     select count(*) into buycount from :ORDED_BUY_INTERVAL;     orderforquantile95 = round(:buycount * (1 - 0.95), 0);     if orderforquantile95 = 0 then         orderforquantile95 = 1;     end if;     INTERVAL_95 = select top :orderforquantile95 DAYDIFF from :ORDED_BUY_INTERVAL;     select top 1 DAYDIFF from :INTERVAL_95 order by DAYDIFF asc; end
